module TopModule (
    input  clk,
    input  L,
    input  q_in,
    input  r_in,
    output Q
);

    // Internal signal to hold the 3-bit state (q[2:0])
    reg [2:0] q;

    // Sequential logic: D flip-flop with load and shift behavior
    always @(posedge clk) begin
        if (L) begin
            // Load mode: shift in r_in as the new MSB (q[2])
            // and shift the previous q[1] and q[0] down
            q <= {r_in, q[1], q[0]};
        end else begin
            // Shift mode: shift left, XOR the two LSBs for the new LSB
            // q[2] shifts out (or stays as MSB depending on interpretation),
            // q[1] becomes previous q[2],
            // q[0] becomes q[1] ^ q[2]
            q <= {q[2], q[1], q[1] ^ q[2]};
        end
    end

    // Assign the output Q to the MSB of the internal state (q[2])
    assign Q = q[2];

endmodule

Prob120_fsm3s.code:
module TopModule (
    input  clk,
    input  reset,
    input  in,
    output out
);

    // State encoding: 2'b00 = A, 2'b01 = B, 2'b10 = C, 2'b11 = D
    reg [1:0] state, next_state;

    // State register (synchronous reset, active-high)
    always @(posedge clk) begin
        if (reset)
            state <= 2'b00;  // A
        else
            state <= next_state;
    end

    // Next-state logic (Moore machine)
    always @(*) begin
        case (state)
            2'b00: begin // State A, out = 0
                if (in)
                    next_state = 2'b01; // A --in=1--> B
                else
                    next_state = 2'b00; // A --in=0--> A
            end
            2'b01: begin // State B, out = 0
                if (in)
                    next_state = 2'b01; // B --in=1--> B
                else
                    next_state = 2'b10; // B --in=0--> C
            end
            2'b10: begin // State C, out = 0
                if (in)
                    next_state = 2'b11; // C --in=1--> D
                else
                    next_state = 2'b00; // C --in=0--> A
            end
            2'b11: begin // State D, out = 1
                if (in)
                    next_state = 2'b10; // D --in=1--> C
                else
                    next_state = 2'b01; // D --in=0--> B
            end
            default: next_state = 2'b00;
        endcase
    end

    // Output logic (Moore: output depends only on state)
    assign out = (state == 2'b11) ? 1'b1 : 1'b0;

endmodule

