    output       f
);

    // Internal signals for decoded address bits
    wire x3 = x[3];
    wire x4 = x[4];
    wire x1 = x[1];
    wire x2 = x[2];

    // Implement the function derived from the K-map:
    // f = x3' & x4' & x2'          (m0, m1, m4, m5)
    //   | x3' & x4  & x1           (m2, m6)
    //   | x3  & x4' & x1'          (m8, m10)
    //   | x3  & x4  & x1' & x2'    (m12, m13)
