module TopModule (
    input  d,
    input  done_counting,
    input  ack,
    input  [9:0] state,
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // One-hot state encoding as specified:
    // S, S1, S11, S110, B0, B1, B2, B3, Count, Wait
    // (10'b0000000001, 10'b0000000010, 10'b0000000100, 10'b0000001000,
    //  10'b0000010000, 10'b0000100000, 10'b0001000000, 10'b0010000000,
    //  10'b0100000000, 10'b1000000000)
    reg [9:0] state_reg, state_next;

    // State register (synchronous update, starts in 'S' at reset)
    // The 'state' input port is included as per specification but the
    // internal state machine uses the one-hot encoded registers.
    always @(posedge d or posedge done_counting) begin
        if (done_counting)
            state_reg <= 10'b0000000001; // Reset to S
        else
            state_reg <= state_next;
    end

    // Next-state logic (derived by inspection of the Moore diagram)
    // The 'd' input and 'done_counting' input control transitions.
    // 'ack' is used in the Wait -> S transition.
    always @(*) begin
        // Default: stay in current state
        state_next = state_reg;

        case (state_reg)
            // S state (10'b0000000001)
            10'b0000000001: begin
                if (d == 1'b1)
                    state_next = 10'b0000000010; // -> S1
                // else stay in S
            end

            // S1 state (10'b0000000010)
            10'b0000000010: begin
                if (d == 1'b1)
                    state_next = 10'b0000000100; // -> S11
                else
                    state_next = 10'b0000000001; // -> S
            end

            // S11 state (10'b0000000100)
            10'b0000000100: begin
                if (d == 1'b1)
                    state_next = 10'b0000001000; // -> S110
                else
                    state_next = 10'b0000000010; // -> S11
            end

            // S110 state (10'b0000001000)
            10'b0000001000: begin
                if (d == 1'b1)
                    state_next = 10'b0000010000; // -> B0
                else
                    state_next = 10'b0000000001; // -> S
            end

            // B0 state (10'b0000010000) -- always goes to B1 next cycle
            10'b0000010000: begin
                state_next = 10'b0000100000; // -> B1
            end

            // B1 state (10'b0000100000) -- always goes to B2 next cycle
            10'b0000100000: begin
                state_next = 10'b0001000000; // -> B2
            end

            // B2 state (10'b0001000000) -- always goes to B3 next cycle
            10'b0001000000: begin
                state_next = 10'b0010000000; // -> B3
            end

            // B3 state (10'b0010000000) -- always goes to Count next cycle
            10'b0010000000: begin
                state_next = 10'b0100000000; // -> Count
            end

            // Count state (10'b0100000000)
            10'b0100000000: begin
                if (done_counting == 1'b1)
                    state_next = 10'b1000000000; // -> Wait
                // else stay in Count
            end

